def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t_i = int(parts[0])
        x_prime = int(parts[1])
        y_i = int(parts[2])
        ops.append((t_i, x_prime, y_i))

    # reachable[i] = set of bananas achievable after operation i
    # We track which states are reachable at each step
    reachable = [set() for _ in range(n + 1)]

    # Initialize: at step 0, only 0 bananas reachable
    reachable[0] = {0}

    # For each step, compute all reachable states
    for i, (t_i, x_prime, y_i) in enumerate(ops):
        # Apply type 1 or type 2 operation up to y_i times
        # x_i = x_prime / 100000
        next_reachable = set()

        for k in reachable[i]:
            # Try applying operation 0 to y_i times
            current = k

            # Add initial state (apply 0 times)
            next_reachable.add(current)

            if t_i == 1:
                # Type 1: k := ceil(k + x_i)
                # ceil(k + x'/100000) = (k * 100000 + x' - 1) // 100000 + 1
                next_k = (k * 100000 + x_prime - 1) // 100000 + 1

                for a in range(1, y_i + 1):
                    current = next_k
                    next_k = (current * 100000 + x_prime - 1) // 100000 + 1
                    if next_k > m or current == next_k:
                        break
                    next_reachable.add(next_k)

                # Add all states from 0 to y_i applications
                for a in range(y_i + 1):
                    if a == 0:
                        next_reachable.add(k)
                    elif a == 1:
                        next_reachable.add(next_k)
                    else:
                        # Need to compute state after a applications
                        temp = k
                        for _ in range(a):
                            temp = (temp * 100000 + x_prime - 1) // 100000 + 1
                        if temp <= m:
                            next_reachable.add(temp)

            elif t_i == 2:
                # Type 2: k := ceil(k * x_i)
                # ceil(k * x'/100000) = (k * x' - 1) // 100000 + 1
                next_k = (k * x_prime - 1) // 100000 + 1

                for a in range(1, y_i + 1):
                    current = next_k
                    next_k = (current * x_prime - 1) // 100000 + 1
                    if next_k > m or current == next_k:
                        break
                    next_reachable.add(next_k)

                # Add all states from 0 to y_i applications
                for a in range(y_i + 1):
                    if a == 0:
                        next_reachable.add(k)
                    elif a == 1:
                        next_reachable.add(next_k)
                    else:
                        temp = k
                        for _ in range(a):
                            temp = (temp * x_prime - 1) // 100000 + 1
                        if temp <= m:
                            next_reachable.add(temp)

        reachable[i + 1] = next_reachable

    # Find earliest time-step for each banana count j in [1, m]
    result = []
    for j in range(1, m + 1):
        for i in range(n):
            if j in reachable[i + 1]:
                result.append(str(i + 1))
                break
        else:
            result.append("-1")

    return ' '.join(result) + ' '

from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return "NO"

    n, m = map(int, lines[0].split())

    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    # Parse edges
    edges = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        if len(parts) >= 2:
            p, q = int(parts[0]), int(parts[1])
            edges.append((p, q))

    # Check if total soldiers match
    if sum(a) != sum(b):
        return "NO"

    # Build adjacency for who can move to whom
    can_move = [[False] * (n + 1) for _ in range(n + 1)]

    # Soldiers can always stay in their own city
    for i in range(1, n + 1):
        can_move[i][i] = True

    # Add bidirectional edges
    for p, q in edges:
        can_move[p][q] = True
        can_move[q][p] = True

    # Max flow algorithm with residual capacities
    INF = float('inf')
    source = 0
    sink = n + 1
    total_nodes = n + 2

    # capacity[u][v] holds remaining capacity (forward edge capacity)
    # flow[u][v] tracks actual flow (not needed if we only store residual)
    cap = [[0] * total_nodes for _ in range(total_nodes)]
    flow = [[0] * total_nodes for _ in range(total_nodes)]

    # Source to each city with capacity a[i-1]
    for i in range(n):
        cap[source][i + 1] = a[i]

    # Each city to sink with capacity b[i-1]
    for i in range(n):
        cap[i + 1][sink] = b[i]

    # Cities can send soldiers to compatible cities
    for i in range(1, n + 1):
        cap[i][i] = INF  # Stay in same city

        for j in range(1, n + 1):
            if can_move[i][j] and i != j:
                cap[i][j] = INF

    def bfs():
        level = [-1] * total_nodes
        level[source] = 0
        queue = deque([source])

        while queue:
            u = queue.popleft()
            for v in range(total_nodes):
                if level[v] == -1 and cap[u][v] > 0:
                    level[v] = level[u] + 1
                    queue.append(v)

        return level

    def dfs(u, t, pushed, level, ptr):
        if pushed == 0 or u == t:
            return pushed

        while ptr[u] < total_nodes and cap[u][ptr[u][u]] > 0 and cap[u][ptr[u]] == 0:
            ptr[u] += 1

        while ptr[u] < total_nodes:
            v = ptr[u]
            if level[u] + 1 != level[v] or cap[u][v] == 0:
                ptr[u] += 1
                continue

            tr = min(pushed, cap[u][v])
            while tr < cap[u][v]:
                pass

            d = dfs(v, t, tr, level, ptr)
            if d == 0:
                ptr[u] += 1

            tr = min(pushed, cap[u][v])
            while tr < cap[u][v]:
                pass

            cap[u][v] -= tr
            cap[v][u] += tr
            return d

        return 0

    # Simpler BFS Dinic implementation
    def max_flow():
        total = 0
        while True:
            level = bfs()
            if level[sink] == -1:
                break

            ptr = list(range(total_nodes))
            while True:
                pushed = dfs(source, sink, INF, level, ptr)
                if pushed == 0:
                    break
                total += pushed

        return total

    total_flow = max_flow()

    if total_flow < sum(a):
        return "NO"
    elif total_flow > sum(a):
        return "NO"

    # Build the output matrix
    # Matrix[i-1][j-1] = soldiers moved from city i to city j
    matrix = [[0] * n for _ in range(n)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # Flow from city i to city j
            matrix[i - 1][j - 1] = cap[j][i]  # residual in edge j<-i = flow in i->j

    result_lines = ["YES"]
    for row in matrix:
        result_lines.append(" ".join(map(str, row)))

    return "\n".join(result_lines)


