def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    grid = [list(line) for line in lines[1:n+1]]

    # Find all free spaces and their bounding box
    dots = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                dots.append((i, j))

    if not dots:
        # No free spaces, return as is
        return '\n'.join(''.join(row) for row in grid)

    min_r, max_r = min(p[0] for p in dots), max(p[0] for p in dots)
    min_c, max_c = min(p[1] for p in dots), max(p[1] for p in dots)

    # Convert all free spaces to walls, then convert back to free spaces within bounding box
    for i in range(n):
        for j in range(m):
            grid[i][j] = '.' if (min_r <= i <= max_r and min_c <= j <= max_c) else '*'

    return '\n'.join(''.join(row) for row in grid)

def solution(s):
    n, m = map(int, s.strip().split())

    if min(n, m) < 2:
        return "0"

    # For small boards, specific handling
    if n * m <= 4:
        return "2" if n * m >= 2 else "0"

    total = n * m

    if min(n, m) % 3 == 0:
        return str(total - 4)
    elif min(n, m) % 3 == 1:
        return str(total - 2)
    else:
        return str(total % 2)

