    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])

    roads = []
    for i in range(1, m + 1):
        if i < len(lines):
            row = lines[i].split()
            u, v, w = int(row[0]), int(row[1]), int(row[2])
            roads.append((u, v, w, i))

    # Handle edge cases
    if n == 1:
        return '0\n\n'

    # Sort roads by weight
    roads.sort(key=lambda x: x[2])

    # Union-Find data structure
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    edges_chosen = []
    capital_count = 0

    # Kruskal's algorithm with capital edge constraint
    for u, v, w, idx in roads:
        is_capital = (u == 1 or v == 1)

        key = find(u)
        val = find(v)

        # Select u-v edge if it connects two disjoint components
        if key != val:
            # Priority: Select k capital edges first
            if is_capital and capital_count < k:
                union(u, v)
                edges_chosen.append(idx)
                capital_count += 1
            else:
                union(u, v)
                edges_chosen.append(idx)

    # Check if all vertices are connected
    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return '-1\n'

    # If we don't have exactly k capital edges, we need more
    # Try to add more capital edges that connect city 1
    if capital_count < k:
        for u, v, w, idx in roads:
            is_capital = (u == 1 or v == 1)
            if is_capital and capital_count < k:
                # Union if not already connected
                if find(u) != find(v):
                    union(u, v)
                    edges_chosen.append(idx)
                    capital_count += 1

    # Final connectivity check
    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return '-1\n'

    # Sort output by edge index
    edges_chosen.sort()

    # Output
    result = str(len(edges_chosen)) + '\n' + ' '.join(map(str, edges_chosen)) + '\n'
    return result

