                if v == path[-1] if path and len(path) >= 2 else False:
                    continue
                if not visited[v]:
                    path.append(v)
                    if dfs_path(v, d + 1):
                        return True
                    path.pop()
                    visited[v] = False

            return False

        if dfs_path(1, 0):
            if len(path) >= min_path_len:
                return f"PATH\n{len(path)}\n{' '.join(map(str, path))}"

    # If neither solution is found, return -1
    return "-1"

