def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n = int(parts[0])
    m = int(parts[1])

    # Parse events and build segments (friends visiting between handle changes)
    segments = []
    current_segment = []

    for i in range(1, len(lines)):
        line = lines[i]
        parts = line.split()
        if parts[0] == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(parts[1])

    if current_segment:
        segments.append(current_segment)

    # Map friends to indices and build conflict graph
    friend_to_idx = {}
    all_friends = set()

    for seg in segments:
        for f in seg:
            all_friends.add(f)

    if not all_friends:
        return '0'

    friend_to_idx = {f: i for i, f in enumerate(all_friends)}
    num_friends = len(friend_to_idx)

    # Build conflict matrix: conflict[i][j] = True if friends i and j appear in same segment
    conflict = [[False] * num_friends for _ in range(num_friends)]

    for seg in segments:
        if len(seg) < 2:
            continue
        seg_indices = [friend_to_idx[f] for f in seg]
        for i in range(len(seg_indices)):
            for j in range(i + 1, len(seg_indices)):
                conflict[seg_indices[i]][seg_indices[j]] = True

    # Maximum Independent Set using brute force for small n
    if num_friends <= 20:
        max_size = 0
        for mask in range(1 << num_friends):
            valid = True
            count = 0
            for i in range(num_friends):
                if (mask >> i) & 1:
                    count += 1
                    for j in range(i + 1, num_friends):
                        if ((mask >> j) & 1) and conflict[i][j]:
                            valid = False
                            break
            if valid:
                max_size = max(max_size, count)
        return str(max_size)
    else:
        # Meet-in-the-middle for larger n
        mid = num_friends // 2

        # Generate all valid independent sets for first half
        first_sets = []

        def dfs_first(idx, current, selected):
            if idx == mid:
                first_sets.append(current.copy())
                return

            # Try excluding idx
            dfs_first(idx + 1, current, selected)

            # Try including idx (check conflicts)
            if all(not conflict[idx][v] for v in selected):
                current.add(idx)
                dfs_first(idx + 1, current, selected)
                current.remove(idx)

        dfs_first(0, set(), set())

        # For each first set, find best compatible set in second half
        max_size = 0

        def dfs_second(idx, current, conflict_with_first):
            nonlocal max_size
            if idx == num_friends:
                max_size = max(max_size, len(current))
                return

            # Try including idx
            if all(not conflict[idx][v] for v in current) and all(not conflict[idx][v] for v in conflict_with_first):
                current.add(idx)
                dfs_second(idx + 1, current, conflict_with_first)
                current.remove(idx)

            # Try excluding idx
            dfs_second(idx + 1, current, conflict_with_first)

        # Build conflict set from first set
        for first_set in first_sets:
            dfs_second(mid, set(), first_set)

        return str(max_size)

def solution(input_data):
    # Parse input
    parts = input_data.strip().split()
    if len(parts) != 3:
        return "-1"

    maxx, maxy, w = map(int, parts)

    # Helper function to reverse a number
    def rev(x):
        return int(str(x)[::-1])

    # Generate all lucky tickets (a, b) within bounds
    lucky = []
    for a in range(1, maxx + 1):
        ra = rev(a)
        if ra == 0:
            continue
        for b in range(1, maxy + 1):
            rb = rev(b)
            if a * b == ra * rb:
                lucky.append((a, b, a * b))  # store a, b, and total

    # Sort lucky tickets by total a*b to try smaller products first
    lucky.sort(key=lambda x: x[2])

    # Find minimum x * y that gives at least w lucky tickets
    min_total = float('inf')
    best_xy = (1, 1)

    # Try different (x, y) combinations in order of increasing x * y
    for total in range(1, maxx * maxy + 1):
        # Find all pairs (a, b) where a <= x and b <= y for x * y = total
        # Brute force for small cases, skip large ones
        found = False
        for x in range(1, min(maxx, total) + 1):
            y = total // x
            if y == 0 or y > maxy:
                continue
            if x > maxx:
                continue

            kids = 0
            for (a, b, _) in lucky:
                if a <= x and b <= y:
                    kids += 1

            if kids >= w:
                if total < min_total:
                    min_total = total
                    best_xy = (x, y)
                found = True
                break  # Since we're iterating by total, first found is optimal
            else:
                # Can't achieve w with this total using current x,y
                # Try next x if y decreases
                pass

        if found:
            break  # Found minimum total

    if min_total == float('inf'):
        return "-1"

    return f"{best_xy[0]} {best_xy[1]}\n"


