def welzl(points: List[List[float]], boundary: List[List[float]]) -> List[float]:
    if len(points) == 0 or len(boundary) == 4:
        return sphere_from(*boundary)

    p = points[len(points)//2]
    rest1 = points[:len(points)//2]
    rest2 = points[len(points)//2:]

    result = welzl(rest1, boundary)
    if dist(result[0], p) <= result[1] + 1e-9:
        return result

    return welzl(rest2, boundary + [p])

