    # Row lengths for hexagonal layout: 3, 4, 5, 4, 3
    row_lengths = [3, 4, 5, 4, 3]

    # Map (row, col) to linear position index
    def coord_to_idx(row, col):
        offset = sum(row_lengths[:row])
        return offset + col

    # Generate all valid lines
    move_lines = []

    # Horizontal lines (each row)
    for r in range(5):
        line = set()
        for c in range(row_lengths[r]):
            line.add(coord_to_idx(r, c))
        if len(line) >= 2:
            move_lines.append(line)

    # Down-right diagonal (r,c) -> (r+1,c+1)
    for start_col in range(row_lengths[0]):
        line = set()
        r, c = 0, start_col
        while r < 5 and c < row_lengths[r]:
            line.add(coord_to_idx(r, c))
            r += 1
            c += 1
        if len(line) >= 2:
            move_lines.append(line)

    # Down-left diagonal (r,c) -> (r+1,c-1)
    for start_col in range(row_lengths[0]):
        line = set()
        r, c = 0, start_col
        while r < 5 and c >= 0 and c < row_lengths[r]:
            line.add(coord_to_idx(r, c))
            r += 1
            c -= 1
        if len(line) >= 2:
            move_lines.append(line)

    # Build position mask
    positions = []
    for r in range(5):
        for c in range(row_lengths[r]):
            pos = coord_to_idx(r, c)
            positions.append((pos, grid[r][c] == 'O'))

    # Create initial state as bitmask
    board_mask = 0
    for r in range(5):
        for c in range(row_lengths[r]):
            if grid[r][c] == 'O':
                board_mask |= (1 << coord_to_idx(r, c))

    # Memoization for Grundy values
    if not hasattr(solution, 'memo'):
        solution.memo = {}

    memo = solution.memo

    def compute_grundy(mask):
        if mask in memo:
            return memo[mask]

        reachable = set()

        # Find all reachable states from current state
        for line in move_lines:
            line_mask = line
            # Check if this line has chocolates (intersection with mask is non-empty)
            if mask & line_mask:
                # Move: remove all chocolates on this line
                removed = 0
                line_mask_val = mask & line_mask
                if line_mask_val:
                    removed = line_mask_val
                    reachable.add(mask ^ line_mask_val)

        if not reachable:
            grundy = 0
        else:
            seen = set()
            for next_mask in reachable:
                seen.add(compute_grundy(next_mask))

            # Find MEX
            mex = 0
            while mex in seen:
                mex += 1
            grundy = mex

        memo[mask] = grundy
        return grundy

    g = compute_grundy(board_mask)

    # Return winner based on Grundy value
    return "Karlsson\n" if g != 0 else "Lillebror\n"


