def solve_dp(n):
    """DP solution for very large numbers"""
    memo = {}

    def dp(num):
        if num == 0:
            return 0
        if num in memo:
            return memo[num]

        digits = set(int(d) for d in str(num))
        min_ops = float('inf')

        for d in digits:
            new_num = num - d
            if new_num > 0:
                ops = dp(new_num)
                if ops + 1 < min_ops:
                    min_ops = ops + 1

        memo[num] = min_ops if min_ops != float('inf') else 0
        return memo[num]

    return dp(n)

