def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    # Only need to check up to sqrt
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True


def get_prime_factors(num):
    factors = set()
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return sorted(factors)


def get_divisors(num):
    divs = [1]
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            divs.append(i)
            if num // i != i:
                divs.append(num // i)
    divs.append(num)
    return sorted(divs)


def get_primes_up_to(n):
    if n < 2:
        return []
    primes = []
    is_p = [True] * (n + 1)
    is_p[0] = is_p[1] = False
    for i in range(2, n + 1):
        if is_p[i]:
            primes.append(i)
            for j in range(i * i, n + 1, i):
                is_p[j] = False
    return primes


