        K = (r / l) ** (1.0 / (n - 1))
        q_max = int(K) + 2

        for q in range(1, q_max + 1):
            q_powers = q ** (n - 1)
            max_p = int(q * K)

            if max_p <= q:
                continue

            for p in range(q + 1, max_p + 1):
                if math.gcd(p, q) == 1:
