def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])

    # Precompute Fibonacci numbers up to 10^18
    fib = [1, 2]
    while True:
        next_fib = fib[-1] + fib[-2]
        if next_fib > 10**18:
            break
        fib.append(next_fib)

    # Create a closure for memoization to persist across test cases
    cache = {}

    def count_decompositions(index, remaining):
        state = (index, remaining)
        if state in cache:
            return cache[state]

        if remaining == 0:
            cache[state] = 1
            return 1

        if index < 0:
            cache[state] = 0
            return 0

        # Option 1: Skip this Fibonacci number
        result = count_decompositions(index - 1, remaining)

        # Option 2: Use this Fibonacci number if it doesn't exceed remaining
        if fib[index] <= remaining:
            result += count_decompositions(index - 1, remaining - fib[index])

        cache[state] = result
        return result

    results = []
    num_fib = len(fib) - 1  # Use 0-indexed last position

    for i in range(1, t + 1):
        n = int(lines[i])
        ans = count_decompositions(num_fib, n)
        results.append(str(ans))

    return '\n'.join(results)

