def solution(problem_input: str):
    lines = problem_input.strip().split('\n')
    if not lines or not lines[0].strip():
        return ""

    m = int(lines[0])
    results = []

    def is_valid_set(a, b, is_final=False):
        """Check if score (a,b) is valid for a set"""
        threshold = 15 if is_final else 25

        # A wins: must reach threshold with at least 2-point lead
        if a >= threshold and b < threshold and a - b >= 2:
            return True
        # A wins after tie-breaker (both >= threshold-1)
        if a >= threshold and b >= threshold and a - b >= 2:
            return True

        # B wins
        if b >= threshold and a < threshold and b - a >= 2:
            return True
        # B wins after tie-breaker
        if b >= threshold and a >= threshold and b - a >= 2:
            return True

        return False

    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        a_total, b_total = int(parts[0]), int(parts[1])

        best_result = None
        best_diff = -float('inf')

        # Try all possible match outcomes (max 5 sets)
        for wa in range(4):
            for wb in range(4):
                if wa + wb > 5:
                    continue
                # Match must end with someone winning 3 sets
                if wa != 3 and wb != 3:
                    continue

                diff = wa - wb
                if diff > best_diff:
                    best_diff = diff
                    best_result = (wa, wb)
                elif diff == best_diff and wa > best_result[0]:
                    best_result = (wa, wb)

        if best_result is None:
            results.append("Impossible")
            continue

        wa, wb = best_result
        total_sets = wa + wb

        # DFS to find valid set scores
        found = False
        solution_set_scores = None

        def dfs(idx, a_rem, b_rem, path):
            nonlocal found, solution_set_scores
            if found:
                return

            if idx == total_sets:
                if a_rem == 0 and b_rem == 0:
                    found = True
                    solution_set_scores = list(path)
                return

            is_final = (idx == total_sets - 1)
            threshold = 15 if is_final else 25

            # Try A wins this set
            for sa in range(min(a_rem, threshold + 30)):
                # Determine max B can score
                if sa < threshold:
                    max_sb = sa - 1 if sa > 0 else 0
                elif sa == threshold:
                    max_sb = threshold - 2
                else:
                    # sa > threshold, B can score up to sa-2 (but no more than threshold+1)
                    max_sb = min(sa - 2, threshold + 2)

                for sb in range(max_sb + 1):
                    if not is_valid_set(sa, sb, is_final):
                        continue
                    if a_rem < sa or b_rem < sb:
                        continue

                    path.append((sa, sb))
                    dfs(idx + 1, a_rem - sa, b_rem - sb, path)
                    path.pop()
                    if found:
                        return

            # Try B wins this set
            for sb in range(min(b_rem, threshold + 30)):
                if sb < threshold:
                    max_sa = sb - 1 if sb > 0 else 0
                elif sb == threshold:
                    max_sa = threshold - 2
                else:
                    max_sa = min(sb - 2, threshold + 2)

                for sa in range(max_sa + 1):
                    if not is_valid_set(sa, sb, is_final):
                        continue
                    if a_rem < sa or b_rem < sb:
                        continue

                    path.append((sa, sb))
                    dfs(idx + 1, a_rem - sa, b_rem - sb, path)
                    path.pop()
                    if found:
                        return

        dfs(0, a_total, b_total, [])

        if found:
            result_line = f"{wa}:{wb}" if wa > 0 or wb > 0 else "0:0"
            sets_line = " ".join([f"{s[0]}:{s[1]}" for s in solution_set_scores])
            results.append(f"{result_line}\n{sets_line} ")
        else:
            results.append("Impossible")

    return "\n".join(results) + "\n"
